type ToolMeta = ToolMetaShape

type ToolResponse = ToolsApiResponse<ToolMeta>

interface ToolPart {
  type: string
  toolCallId?: string
  toolName?: string
  state?: string
  input?: unknown
  output?: unknown
  result?: unknown
  args?: unknown
