import { useEffect, useRef, useCallback } from 'react'
import { useConvex } from 'convex/react'
import type { Id } from '../../convex/_generated/dataModel'
import { BinaryFileSync, isBinaryFile } from '@/lib/sync/BinaryFileSync'

/**
 * useBinaryFileSync - Syncs binary files (images, videos, etc.) via replica LFS APIs.
 *
 * This hook:
 * 1. Listens for local binary file changes via Electron file watcher
 * 2. Uploads changed binary files to replica object storage
 * 3. Enqueues a Git replica snapshot for reconciliation
 * 4. Processes queued uploads when connection is restored
 *
 * Binary files are synced separately from text files because:
 * - They can't be meaningfully merged as CRDTs
 * - They're often large and would bloat the Y.Doc
 * - Conflict handling is done at replica merge/apply stage
 */
export function useBinaryFileSync(
  projectId: Id<'projects'> | null,
  projectPath: string | null,
  userId: Id<'users'> | null
): { pendingUploads: number } {
  const convex = useConvex()
  const binarySyncRef = useRef<BinaryFileSync | null>(null)

  // Initialize BinaryFileSync
  useEffect(() => {
    if (!projectId || !projectPath || !userId) {
      binarySyncRef.current = null
      return
    }

    binarySyncRef.current = new BinaryFileSync(projectId, projectPath, convex, userId)

    // Process any queued uploads from previous sessions
    void binarySyncRef.current.processQueue()

    return () => {
      binarySyncRef.current?.destroy()
      binarySyncRef.current = null
    }
  }, [convex, projectId, projectPath, userId])

  // Handle local binary file changes
  useEffect(() => {
    if (!projectPath || !binarySyncRef.current) return

    const handleExternalFileChange = (data: {
      filePath: string
      origin?: string
      isBinary: boolean
      sizeBytes: number
      isDirectory?: boolean
    }) => {
      if (!data.filePath.startsWith(projectPath)) return
      if (data.isDirectory) return
      const relativePath = data.filePath
        .slice(projectPath.length)
        .replace(/^[/\\]+/, '')
        .replace(/\\/g, '/')

      // Only handle binary files
      if (!data.isBinary && !isBinaryFile(relativePath)) return

      // Don't re-upload files we just downloaded
      if (data.origin === 'remote' || data.origin === 'sync') return

      console.log(`[BinaryFileSync] Local binary file changed: ${relativePath}`)
      binarySyncRef.current?.uploadBinaryFile(relativePath)
    }

    // Subscribe to local file changes via Electron
    const unsubscribe = window.electronAPI.yjs.onExternalFileMetaChange(
      handleExternalFileChange
    )

    return () => {
      unsubscribe()
    }
  }, [projectPath])

  // Handle reconnection - process queued uploads
  useEffect(() => {
    const handleOnline = () => {
      console.log('[BinaryFileSync] Online, processing upload queue...')
      binarySyncRef.current?.processQueue()
    }

    window.addEventListener('online', handleOnline)

    return () => {
      window.removeEventListener('online', handleOnline)
    }
  }, [])

  const getPendingUploads = useCallback(() => {
    return binarySyncRef.current?.getPendingCount() ?? 0
  }, [])

  return {
    pendingUploads: getPendingUploads(),
  }
}

import { useEffect, useRef, useState } from 'react'
import { useQuery } from 'convex/react'
import { api } from '../../convex/_generated/api'
import type { Id } from '../../convex/_generated/dataModel'
import {
  getCachedPreviewUrl,
  fetchAndCachePreviewUrl,
  invalidatePreviewImageCache,
} from '@/lib/previewImageCache'

export interface UseCachedPreviewUrlOptions {
  /** When false, skips the Convex query and fetch (e.g. for lazy loading). Default true. */
  enabled?: boolean
}

/**
 * Returns the project preview image URL, using an in-memory cache so the image
 * doesn't re-load from the network every time the project list is shown.
 * Call invalidatePreviewImageCache(projectId) after uploading a new preview.
 */
export function useCachedPreviewUrl(
  projectId: Id<'projects'> | undefined,
  userId?: Id<'users'>,
  options?: UseCachedPreviewUrlOptions
): {
  url: string | null
  isLoading: boolean
  error: boolean
} {
  const enabled = options?.enabled !== false
  const sourceUrl = useQuery(
    api.projects.getPreviewImageUrl,
    projectId && userId && enabled ? { projectId, userId } : 'skip'
  )
  // Track which projectId the current blobUrl belongs to so we never show another project's screenshot
  const [state, setState] = useState<{ blobUrl: string | null; forProjectId: string | null }>(() => ({
    blobUrl: projectId ? getCachedPreviewUrl(projectId) ?? null : null,
    forProjectId: projectId ?? null,
  }))
  const [error, setError] = useState(false)
  const fetchingRef = useRef<string | null>(null)

  const [prevDeps, setPrevDeps] = useState({ projectId, sourceUrl })
  if (projectId !== prevDeps.projectId || sourceUrl !== prevDeps.sourceUrl) {
    setPrevDeps({ projectId, sourceUrl })

    if (!projectId) {
      setState({ blobUrl: null, forProjectId: null })
      setError(false)
    } else if (sourceUrl === undefined) {
      const cached = getCachedPreviewUrl(projectId)
      setState({ blobUrl: cached ?? null, forProjectId: projectId })
      setError(false)
    } else if (sourceUrl === null) {
      invalidatePreviewImageCache(projectId)
      setState({ blobUrl: null, forProjectId: projectId })
      setError(false)
    } else {
      const cached = getCachedPreviewUrl(projectId)
      if (cached) {
        setState({ blobUrl: cached, forProjectId: projectId })
        setError(false)
      }
    }
  }

  useEffect(() => {
    if (!projectId || sourceUrl === undefined || sourceUrl === null) {
      return
    }

    const cached = getCachedPreviewUrl(projectId)
    if (cached) {
      return
    }

    // Fetch and cache (avoid duplicate in-flight fetches)
    if (fetchingRef.current === projectId) return
    fetchingRef.current = projectId
    setError(false)

    fetchAndCachePreviewUrl(projectId, sourceUrl)
      .then((url) => {
        if (fetchingRef.current === projectId) {
          setState({ blobUrl: url, forProjectId: projectId })
        }
      })
      .catch(() => {
        if (fetchingRef.current === projectId) {
          setError(true)
          setState({ blobUrl: null, forProjectId: projectId })
        }
      })
      .finally(() => {
        fetchingRef.current = null
      })
  }, [projectId, sourceUrl])

  // Only use blobUrl if it belongs to the current project (avoids showing another project's screenshot)
  const url =
    state.forProjectId === projectId ? state.blobUrl ?? null : null
  const isLoading =
    sourceUrl !== undefined && sourceUrl !== null && url === null && !error

  return {
    url,
    isLoading,
    error,
  }
}

export { invalidatePreviewImageCache } from '@/lib/previewImageCache'

