import { useEffect, useMemo, useRef, useState } from 'react'
import { useChat } from '@ai-sdk/react'
import {
  lastAssistantMessageIsCompleteWithToolCalls,
  lastAssistantMessageIsCompleteWithApprovalResponses,
} from 'ai'
import { useAiChatTransport, type UseAiChatTransportArgs, type ChatMessageLike } from '@/lib/ai/useAiChatTransport'
import {
  readLatestRetryHint,
  resolveAutoRetryDelayMs,
  shouldAutoRetryFromHint,
  type RetryHint,
} from '@/lib/ai/retryHints'
import { parseBillingError, type BillingErrorData } from '@/lib/ai/billingErrors'

// Common function for deduplication across the app
export function dedupeMessagesById<T extends ChatMessageLike>(messages: T[]): T[] {
  if (messages.length <= 1) return messages

  const lastIndexById = new Map<string, number>()
  for (let index = 0; index < messages.length; index += 1) {
    const messageId = messages[index]?.id
    if (!messageId) continue
    lastIndexById.set(messageId, index)
  }

  return messages.filter((message, index) => {
    if (!message.id) return true
    return lastIndexById.get(message.id) === index
  })
}

export interface UseCozeaChatArgs {
  transportArgs: UseAiChatTransportArgs
  chatOptions?: Omit<Parameters<typeof useChat>[0], 'transport' | 'sendAutomaticallyWhen'>
  autoRetry?: {
    enabled?: boolean
    maxAttempts?: number
    initialDelayMs?: number
    maxDelayMs?: number
    backoffFactor?: number
  }
  onBillingError?: (error: BillingErrorData) => void
  onError?: (error: Error) => void
}

export interface ChatAutoRetryState {
  scheduled: boolean
  attempt: number
  maxAttempts: number
  nextRetryAt: number | null
  exhausted: boolean
  reasonCode?: RetryHint['code']
}

function resolveRetryScopeKey(messages: Array<{ id?: string; role?: string }>): string {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index]
    if (message.role !== 'user') continue
    if (typeof message.id === 'string' && message.id.trim().length > 0) {
      return message.id
    }
    return `user-${index}`
  }

  const lastMessage = messages[messages.length - 1]
  if (lastMessage && typeof lastMessage.id === 'string' && lastMessage.id.trim().length > 0) {
    return `fallback-${lastMessage.id}`
  }
  return 'conversation'
}

export function useCozeaChat({
  transportArgs,
  chatOptions,
  autoRetry,
  onBillingError,
  onError,
}: UseCozeaChatArgs) {
  const [billingError, setBillingError] = useState<BillingErrorData | null>(null)
  const { transport, setConversationId } = useAiChatTransport(transportArgs)
  const retryTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const retryAttemptsByScopeRef = useRef<Map<string, number>>(new Map())
  const scheduledRetryKeyRef = useRef<string | null>(null)

  const chatHook = useChat({
    transport,
    sendAutomaticallyWhen: ({ messages }) =>
      lastAssistantMessageIsCompleteWithToolCalls({ messages }) ||
      lastAssistantMessageIsCompleteWithApprovalResponses({ messages }),
    ...chatOptions,
    onError: (err: Error) => {
      console.error('Chat error:', err)
      const parsedBillingErr = parseBillingError(err, {
        workspaceScoped: Boolean(transportArgs.organizationId),
      })
      if (parsedBillingErr) {
        setBillingError(parsedBillingErr)
        onBillingError?.(parsedBillingErr)
      }
      onError?.(err)
      if (chatOptions && 'onError' in chatOptions && typeof chatOptions.onError === 'function') {
        chatOptions.onError(err)
      }
    }
  })

  const dedupedMessages = useMemo(() => dedupeMessagesById(chatHook.messages), [chatHook.messages])

  const retryHint = useMemo(() => {
    // useChat types aren't perfectly aligned with our parts, so we cast to check parts safely
    return readLatestRetryHint(
      dedupedMessages as Array<{ parts: Array<{ type: string } & Record<string, unknown>> }>
    )
  }, [dedupedMessages])

  const retryScopeKey = useMemo(() => {
    const scopedMessages = dedupedMessages as Array<{ id?: string; role?: string }>
    return resolveRetryScopeKey(scopedMessages)
  }, [dedupedMessages])

  const autoRetrySettings = useMemo(() => {
    const maxAttempts = Math.max(0, Math.floor(autoRetry?.maxAttempts ?? 2))
    return {
      enabled: autoRetry?.enabled === true,
      maxAttempts,
      initialDelayMs: Math.max(250, Math.floor(autoRetry?.initialDelayMs ?? 2000)),
      maxDelayMs: Math.max(250, Math.floor(autoRetry?.maxDelayMs ?? 30000)),
      backoffFactor: Math.max(1, autoRetry?.backoffFactor ?? 2),
    }
  }, [
    autoRetry?.enabled,
    autoRetry?.maxAttempts,
    autoRetry?.initialDelayMs,
    autoRetry?.maxDelayMs,
    autoRetry?.backoffFactor,
  ])

  const [autoRetryState, setAutoRetryState] = useState<ChatAutoRetryState>({
    scheduled: false,
    attempt: 0,
    maxAttempts: autoRetrySettings.maxAttempts,
    nextRetryAt: null,
    exhausted: false,
  })

  const [prevRetryDeps, setPrevRetryDeps] = useState({
    chatStatus: chatHook.status,
    enabled: autoRetrySettings.enabled,
    maxAttempts: autoRetrySettings.maxAttempts,
    retryHint,
    retryScopeKey
  })

  if (
    chatHook.status !== prevRetryDeps.chatStatus ||
    autoRetrySettings.enabled !== prevRetryDeps.enabled ||
    autoRetrySettings.maxAttempts !== prevRetryDeps.maxAttempts ||
    retryHint !== prevRetryDeps.retryHint ||
    retryScopeKey !== prevRetryDeps.retryScopeKey
  ) {
    setPrevRetryDeps({
      chatStatus: chatHook.status,
      enabled: autoRetrySettings.enabled,
      maxAttempts: autoRetrySettings.maxAttempts,
      retryHint,
      retryScopeKey
    })

    if (!autoRetrySettings.enabled) {
      if (retryTimerRef.current) {
        clearTimeout(retryTimerRef.current)
        retryTimerRef.current = null
      }
      scheduledRetryKeyRef.current = null
    } else if (chatHook.status !== 'error') {
      if (retryTimerRef.current) {
        clearTimeout(retryTimerRef.current)
        retryTimerRef.current = null
      }
      scheduledRetryKeyRef.current = null
      if (
        autoRetryState.scheduled ||
        autoRetryState.nextRetryAt !== null ||
        autoRetryState.maxAttempts !== autoRetrySettings.maxAttempts ||
        autoRetryState.exhausted !== false
      ) {
        setAutoRetryState({
          ...autoRetryState,
          attempt: 0,
          scheduled: false,
          nextRetryAt: null,
          maxAttempts: autoRetrySettings.maxAttempts,
          exhausted: false,
          reasonCode: undefined,
        })
      }
    } else if (shouldAutoRetryFromHint(retryHint)) {
      const maxAttemptsForHint =
        retryHint.code === 'duplicate_response_item_id'
          ? Math.min(1, autoRetrySettings.maxAttempts)
          : autoRetrySettings.maxAttempts

      if (maxAttemptsForHint <= 0) {
        setAutoRetryState({
          ...autoRetryState,
          scheduled: false,
          nextRetryAt: null,
          maxAttempts: maxAttemptsForHint,
          exhausted: true,
          reasonCode: retryHint.code,
        })
      } else {
        const completedAttempts = retryAttemptsByScopeRef.current.get(retryScopeKey) ?? 0
        if (completedAttempts >= maxAttemptsForHint) {
          setAutoRetryState({
            ...autoRetryState,
            scheduled: false,
            nextRetryAt: null,
            attempt: completedAttempts,
            maxAttempts: maxAttemptsForHint,
            exhausted: true,
            reasonCode: retryHint.code,
          })
        }
      }
    }
  }

  useEffect(() => {
    return () => {
      if (!retryTimerRef.current) return
      clearTimeout(retryTimerRef.current)
      retryTimerRef.current = null
      scheduledRetryKeyRef.current = null
    }
  }, [])

  const chatStatus = chatHook.status
  const clearError = chatHook.clearError
  const regenerate = chatHook.regenerate

  useEffect(() => {
    if (!autoRetrySettings.enabled || chatStatus !== 'error' || !shouldAutoRetryFromHint(retryHint)) {
      return
    }

    const maxAttemptsForHint =
      retryHint.code === 'duplicate_response_item_id'
        ? Math.min(1, autoRetrySettings.maxAttempts)
        : autoRetrySettings.maxAttempts

    if (maxAttemptsForHint <= 0) return

    const completedAttempts = retryAttemptsByScopeRef.current.get(retryScopeKey) ?? 0
    if (completedAttempts >= maxAttemptsForHint) return

    const nextAttempt = completedAttempts + 1
    const scheduledRetryKey = `${retryScopeKey}:${retryHint.code}:${nextAttempt}`
    if (scheduledRetryKeyRef.current === scheduledRetryKey) {
      return
    }

    if (retryTimerRef.current) {
      clearTimeout(retryTimerRef.current)
      retryTimerRef.current = null
    }

    const retryDelayMs = resolveAutoRetryDelayMs({
      attempt: nextAttempt,
      hint: retryHint,
      initialDelayMs: autoRetrySettings.initialDelayMs,
      maxDelayMs: autoRetrySettings.maxDelayMs,
      backoffFactor: autoRetrySettings.backoffFactor,
    })
    const nextRetryAt = Date.now() + retryDelayMs

    scheduledRetryKeyRef.current = scheduledRetryKey
    setAutoRetryState({
      scheduled: true,
      attempt: nextAttempt,
      maxAttempts: maxAttemptsForHint,
      nextRetryAt,
      exhausted: false,
      reasonCode: retryHint.code,
    })

    retryTimerRef.current = setTimeout(() => {
      retryTimerRef.current = null
      scheduledRetryKeyRef.current = null
      retryAttemptsByScopeRef.current.set(retryScopeKey, nextAttempt)

      setAutoRetryState((current) => ({
        ...current,
        scheduled: false,
        nextRetryAt: null,
        attempt: nextAttempt,
        maxAttempts: maxAttemptsForHint,
        exhausted: nextAttempt >= maxAttemptsForHint,
        reasonCode: retryHint.code,
      }))

      clearError()
      void regenerate().catch((error) => {
        console.warn('Automatic chat retry failed:', error)
      })
    }, retryDelayMs)
  }, [
    autoRetrySettings.backoffFactor,
    autoRetrySettings.enabled,
    autoRetrySettings.initialDelayMs,
    autoRetrySettings.maxAttempts,
    autoRetrySettings.maxDelayMs,
    chatStatus,
    clearError,
    regenerate,
    retryHint,
    retryScopeKey,
  ])

  return {
    ...chatHook,
    dedupedMessages,
    retryHint,
    autoRetryState,
    billingError,
    setBillingError,
    setConversationId,
    transport
  }
}

import { useEffect, useMemo, useState } from 'react'

import {
  buildEncodedProviderAuthHeader,
  inferProviderFromModelId,
  isManagedProvider,
} from '@/lib/ai/providerAuth'

export interface UseProviderAuthResolutionArgs {
  organizationId?: string | null
  modelId: string
  preferredProvider?: string | null
  retries?: number
  retryDelayMs?: number
  resolveWhenUnavailable?: boolean
  refreshKey?: string | number | null | undefined
}

export interface UseProviderAuthResolutionResult {
  provider: string | null
  requiresLocalAuth: boolean
  managedProvider: boolean
  header: string | null
  loading: boolean
  resolved: boolean
  error: string | null
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms)
  })
}

export function useProviderAuthResolution(
  args: UseProviderAuthResolutionArgs
): UseProviderAuthResolutionResult {
  const {
    organizationId,
    modelId,
    preferredProvider,
    retries = 1,
    retryDelayMs = 250,
    resolveWhenUnavailable = false,
    refreshKey,
  } = args

  const provider = useMemo(() => {
    const explicit = typeof preferredProvider === 'string' ? preferredProvider.trim().toLowerCase() : ''
    if (explicit) {
      return explicit
    }
    return inferProviderFromModelId(modelId)
  }, [modelId, preferredProvider])

  const managedProvider = Boolean(provider && isManagedProvider(provider))
  const requiresLocalAuth = Boolean(provider && !managedProvider)
  const normalizedOrgId = typeof organizationId === 'string' ? organizationId.trim() : ''
  const depsKey = `${normalizedOrgId}:${provider}:${managedProvider}:${refreshKey}`

  const [header, setHeader] = useState<string | null>(null)
  const [loading, setLoading] = useState(() => {
    if (!normalizedOrgId || !provider || managedProvider) return false
    return true
  })
  const [resolved, setResolved] = useState(() => {
    if (!normalizedOrgId || !provider) return false
    if (managedProvider) return true
    return false
  })
  const [error, setError] = useState<string | null>(null)
  const [prevDepsKey, setPrevDepsKey] = useState(depsKey)

  if (depsKey !== prevDepsKey) {
    setPrevDepsKey(depsKey)
    if (!normalizedOrgId || !provider) {
      setHeader(null)
      setLoading(false)
      setResolved(false)
      setError(null)
    } else if (managedProvider) {
      setHeader(null)
      setLoading(false)
      setResolved(true)
      setError(null)
    } else {
      setHeader(null)
      setLoading(true)
      setResolved(false)
      setError(null)
    }
  }

  useEffect(() => {
    let cancelled = false
    const attempts = Math.max(1, Math.floor(retries))
    const baseDelay = Math.max(50, Math.floor(retryDelayMs))

    if (!normalizedOrgId || !provider || managedProvider) {
      return
    }

    void (async () => {
      let finalError = 'Provider authentication is not ready on this device.'
      for (let attempt = 0; attempt < attempts; attempt += 1) {
        const result = await buildEncodedProviderAuthHeader({
          provider,
          modelId,
          organizationId: normalizedOrgId,
        })
        if (cancelled) return

        if (result.header) {
          setHeader(result.header)
          setLoading(false)
          setResolved(true)
          setError(null)
          return
        }

        finalError = result.error || finalError
        if (attempt < attempts - 1) {
          await wait(baseDelay * (attempt + 1))
          if (cancelled) return
        }
      }

      if (cancelled) return
      setHeader(null)
      setLoading(false)
      setResolved(resolveWhenUnavailable)
      setError(finalError)
    })()

    return () => {
      cancelled = true
    }
  }, [
    organizationId,
    modelId,
    provider,
    managedProvider,
    retries,
    retryDelayMs,
    resolveWhenUnavailable,
    refreshKey,
  ])

  return {
    provider,
    requiresLocalAuth,
    managedProvider,
    header,
    loading,
    resolved,
    error,
  }
}

import { useCallback, useEffect, useState } from 'react'
import { useMutation } from 'convex/react'

import { api } from '../../convex/_generated/api'
import { useAuth } from '@/contexts/AuthContext'
import { useScopedSettingsPage } from '@/hooks/useScopedSettingsPage'
import { getModelCatalog, type ModelApiModel } from '@/lib/ai/modelCatalogClient'
import { readScopedJsonValue, writeScopedJsonValue } from '@/lib/settings/scopedLocalState'

interface UseScopedModelSelectionDataOptions {
  route?: string
}

const SAVED_MODELS_STORAGE_PREFIX = 'cozea.settings.modelSelection.savedModels.v1'
const DEFAULT_ALLOWED_PROVIDERS = ['openai', 'anthropic', 'google', 'xai', 'moonshotai'] as const

function loadSavedModelIds(scope: string): string[] {
  const parsed = readScopedJsonValue<unknown>(SAVED_MODELS_STORAGE_PREFIX, scope, [])
  if (!Array.isArray(parsed)) return []

  return Array.from(new Set(
    parsed
      .filter((value): value is string => typeof value === 'string' && value.trim().length > 0)
      .map((value) => value.trim()),
  ))
}

function saveSavedModelIds(scope: string, modelIds: string[]): void {
  const normalized = Array.from(new Set(
    modelIds
      .filter((value): value is string => typeof value === 'string' && value.trim().length > 0)
      .map((value) => value.trim()),
  ))

  writeScopedJsonValue(SAVED_MODELS_STORAGE_PREFIX, scope, normalized)
}

export function useScopedModelSelectionData(options: UseScopedModelSelectionDataOptions = {}) {
  const {
    user,
    logout,
    accessToken,
    convexUserId,
  } = useAuth()
  const settingsPage = useScopedSettingsPage({
    route: options.route,
    surfaceId: 'modelSelection',
  })
  const scopedOrganizationId = settingsPage.resolvedScope.scopedOrganizationId
  const workspaceScoped = settingsPage.workspaceScoped
  const {
    canManageWorkspaceAiModelPolicy,
    convexOrg,
  } = settingsPage.workspaceAccess
  const storageScope = settingsPage.storageScopeKey
  const storageMode = settingsPage.storageMode
  const updateOrganizationAiSettings = useMutation(api.organizations.updateAiSettings)

  const [availableModels, setAvailableModels] = useState<ModelApiModel[]>([])
  const [isLoadingModels, setIsLoadingModels] = useState(false)
  const [modelsError, setModelsError] = useState<string | null>(null)
  const [savedModelIds, setSavedModelIds] = useState<string[]>([])
  const [isSavingScopedModels, setIsSavingScopedModels] = useState(false)
  const [saveScopedModelsError, setSaveScopedModelsError] = useState<string | null>(null)

  const [prevSavedDeps, setPrevSavedDeps] = useState({ allowedModels: convexOrg?.aiSettings?.allowedModels, storageMode, storageScope })
  if (
    prevSavedDeps.storageMode !== storageMode ||
    prevSavedDeps.storageScope !== storageScope ||
    prevSavedDeps.allowedModels !== convexOrg?.aiSettings?.allowedModels
  ) {
    setPrevSavedDeps({ allowedModels: convexOrg?.aiSettings?.allowedModels, storageMode, storageScope })
    if (storageMode === 'cloud') {
      const allowedModels = convexOrg?.aiSettings?.allowedModels ?? []
      setSavedModelIds(Array.from(new Set(allowedModels)))
    } else {
      setSavedModelIds(loadSavedModelIds(storageScope))
    }
  }

  const [prevAvailableDeps, setPrevAvailableDeps] = useState({ accessToken, scopedOrganizationId, isWorkspaceAccessDenied: settingsPage.isWorkspaceAccessDenied })
  if (
    prevAvailableDeps.accessToken !== accessToken ||
    prevAvailableDeps.scopedOrganizationId !== scopedOrganizationId ||
    prevAvailableDeps.isWorkspaceAccessDenied !== settingsPage.isWorkspaceAccessDenied
  ) {
    setPrevAvailableDeps({ accessToken, scopedOrganizationId, isWorkspaceAccessDenied: settingsPage.isWorkspaceAccessDenied })
    if (!accessToken || !scopedOrganizationId || settingsPage.isWorkspaceAccessDenied) {
      setAvailableModels([])
      setModelsError(null)
      setIsLoadingModels(false)
    }
  }

  useEffect(() => {
    if (!accessToken || !scopedOrganizationId || settingsPage.isWorkspaceAccessDenied) {
      return
    }

    let cancelled = false
    setIsLoadingModels(true)
    setModelsError(null)

    getModelCatalog({
      organizationId: scopedOrganizationId,
      accessToken,
    })
      .then((data) => {
        if (cancelled) return
        setAvailableModels(Array.isArray(data.models) ? data.models : [])
      })
      .catch((error) => {
        if (cancelled) return
        const message = error instanceof Error && error.message
          ? error.message
          : 'Failed to load models'
        setModelsError(message)
        setAvailableModels([])
      })
      .finally(() => {
        if (cancelled) return
        setIsLoadingModels(false)
      })

    return () => {
      cancelled = true
    }
  }, [accessToken, scopedOrganizationId, settingsPage.isWorkspaceAccessDenied])

  const persistSavedModelIds = useCallback((next: string[], previous: string[]) => {
    if (storageMode === 'local') {
      saveSavedModelIds(storageScope, next)
      return
    }

    if (!convexOrg?._id || !convexUserId) {
      setSavedModelIds(previous)
      return
    }

    setSaveScopedModelsError(null)
    setIsSavingScopedModels(true)

    void updateOrganizationAiSettings({
      orgId: convexOrg._id,
      userId: convexUserId,
      aiSettings: {
        allowedProviders:
          convexOrg.aiSettings?.allowedProviders && convexOrg.aiSettings.allowedProviders.length > 0
            ? convexOrg.aiSettings.allowedProviders
            : [...DEFAULT_ALLOWED_PROVIDERS],
        allowedModels: next,
        allowProviderTools: convexOrg.aiSettings?.allowProviderTools,
        allowWebSearch: convexOrg.aiSettings?.allowWebSearch,
        maxReasoningDepth: convexOrg.aiSettings?.maxReasoningDepth,
        monthlySpendingCapCents: convexOrg.aiSettings?.monthlySpendingCapCents,
        defaultModelTier: convexOrg.aiSettings?.defaultModelTier,
      },
    })
      .catch((error) => {
        const message =
          error instanceof Error && error.message
            ? error.message
            : 'Failed to save workspace model selection.'
        setSaveScopedModelsError(message)
        setSavedModelIds(previous)
      })
      .finally(() => {
        setIsSavingScopedModels(false)
      })
  }, [convexOrg, convexUserId, storageMode, storageScope, updateOrganizationAiSettings])

  const toggleSavedModel = useCallback((modelId: string) => {
    const availableSet = new Set(availableModels.map((model) => model.id))

    setSavedModelIds((previous) => {
      if (previous.includes(modelId)) {
        const availableSaved = previous.filter((id) => availableSet.has(id))
        const isLastAvailableSaved =
          availableSaved.length === 1 && availableSaved[0] === modelId
        if (isLastAvailableSaved) {
          return previous
        }
      }

      const next = previous.includes(modelId)
        ? previous.filter((id) => id !== modelId)
        : [...previous, modelId]

      persistSavedModelIds(next, previous)
      return next
    })
  }, [availableModels, persistSavedModelIds])

  return {
    settingsPage,
    user,
    logout,
    accessToken,
    convexUserId,
    scopedOrganizationId,
    workspaceScoped,
    canManageWorkspaceAiModelPolicy,
    convexOrg,
    storageScope,
    storageMode,
    availableModels,
    isLoadingModels,
    modelsError,
    savedModelIds,
    toggleSavedModel,
    isSavingScopedModels,
    saveScopedModelsError,
  }
}

